{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Methoxsalen, the closest analogue (Morgan 0.4186), has relatively low systemic bioavailability in humans after oral doses up to 10 mg, supporting low F for the methoxy-coumarin scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Apocynin, a small methoxy-phenol sharing the OMe/OH substitution pattern, has human oral bioavailability <10%, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Ferulic acid, a methoxy-hydroxycinnamic acid with a similar phenolic/methoxy motif, shows only 3-10% oral bioavailability in humans, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Curcumin has absolute oral bioavailability of about 1% in humans due to poor solubility and rapid conjugation; although larger, it reinforces the low-bioavailability pattern of polyphenolic methoxy-phenols.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Chrysin, a phenolic flavonoid, has oral bioavailability <1% in healthy volunteers, supporting low F for phenolic natural products.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Isoeugenol, a small methoxy-phenol without the coumarin lactone, showed 35.8-39.0% oral bioavailability in humans, providing a contradictory intermediate-F data point with lower structural transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Prediction is low. Although scopoletin has favorable physicochemical properties, the closest experimental analogues—methoxsalen, apocynin, and ferulic acid—show low human oral bioavailability (<10% or relatively low), and larger polyphenols such as curcumin and chrysin also show very low F. The single contradictory isoeugenol result (35.8-39%) is less transferable because it lacks the coumarin lactone and has a different metabolic profile. Overall, F < 20% is better supported.",
  "evidence_gaps": [
    "No direct human or animal oral bioavailability data for scopoletin itself.",
    "Extrapolation relies on analogues with moderate Morgan similarity (0.27-0.42).",
    "The specific impact of the coumarin lactone on absorption and first-pass conjugation relative to simple phenolics is not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

